def main():
    raw = DB.read_bytes()
    enc = 'utf-8-sig' if raw[:3]==b'\xef\xbb\xbf' else 'utf-8'
    with DB.open('r',encoding=enc,newline='') as f:
        rows=list(csv.reader(f))
    updated=0
    for row in rows:
        if len(row)<14: continue
        key=(row[0],row[1],row[2],row[4],row[5],row[6],row[7])
        if key in C and row[8]=='':
            cat,txt,lbl,sc,pr,task=C[key]
            row[3]=cat; row[8]=txt; row[9]=lbl; row[10]=''; row[11]=sc; row[12]=pr; row[13]=task
            updated+=1
    with DB.open('w',encoding='utf-8-sig',newline='') as f:
        csv.writer(f).writerows(rows)
    print(f"updated:{updated}")
if __name__=='__main__': main()
